function validateFileNumber1(elementValue)
{  
	if (elementValue == null) return true;

    var FileNumberPattern1 =/^[a-zA-Z]{3}(-| |)[0-9]{5}(-| |)[0-9]{2}$/;
	return(FileNumberPattern1.test(elementValue));
}

function validateFileNumber2(elementValue)
{  
	if (elementValue == null) return true;

    var FileNumberPattern2 =/^[a-zA-Z]{3}(-| |)[a-zA-Z]{1}(-| |)[0-9]{6}(-| |)[0-9]{2}$/;
	return(FileNumberPattern2.test(elementValue));
}

if (!validateFileNumber1(this.rawValue) && !validateFileNumber2(this.rawValue))
{
    app.alert("File Number field failed validation. Please use the format TSL-12345-22 or LTB-L-123456-22.");  //Le champ Numéro de dossier n'a pu être validé. Veuillez utiliser le format TSL-12345-22 ou LTB-L-123456-22.
    this.rawValue = "";
    xfa.host.setFocus(this);
}
else
{
	this.rawValue = this.rawValue.toUpperCase();
}
